<template>
  <MainLayout>
    <main class="video-page">
      <aside class="config-panel">
        <div class="config-scroll">
          <div class="panel-heading"><div><VideoCameraIcon /><div><h1>视频生成</h1></div></div><span v-if="taskId" :class="['status-chip', statusTone]">{{ statusLabel }}</span></div>

          <section class="config-section">
            <div class="section-title"><div><strong>参考素材</strong></div><span>{{ references.length }}/9</span></div>
            <div class="frame-grid"><div class="frame-tile"><label :class="{ filled: firstFrame, dragging: frameDrag === 'first' }" @dragover.prevent="frameDrag = 'first'" @dragleave.prevent="frameDrag = ''" @drop.prevent="dropFrame('first', $event)"><PhotoIcon /><strong>首帧</strong><small>{{ firstFrame ? '已上传' : '添加图片' }}</small><input type="file" accept="image/*" @change="pickFrame('first', $event)"></label><button v-if="firstFrame" type="button" aria-label="移除首帧" @click="firstFrame = ''"><XMarkIcon /></button></div><div class="frame-tile"><label :class="{ filled: lastFrame, dragging: frameDrag === 'last' }" @dragover.prevent="frameDrag = 'last'" @dragleave.prevent="frameDrag = ''" @drop.prevent="dropFrame('last', $event)"><PhotoIcon /><strong>尾帧</strong><small>{{ lastFrame ? '已上传' : '添加图片' }}</small><input type="file" accept="image/*" @change="pickFrame('last', $event)"></label><button v-if="lastFrame" type="button" aria-label="移除尾帧" @click="lastFrame = ''"><XMarkIcon /></button></div></div>
            <label class="asset-upload-bar" :class="{ dragging: isDraggingFiles, blocked: firstFrame || lastFrame }" @dragover.prevent="!firstFrame && !lastFrame && (isDraggingFiles = true)" @dragleave.prevent="isDraggingFiles = false" @drop.prevent="dropMixedMedia"><span class="asset-upload-icon"><PhotoIcon /></span><span><strong>{{ firstFrame || lastFrame ? '参考素材不可用' : '添加参考素材' }}</strong><small>{{ firstFrame || lastFrame ? '清除首尾帧后可上传' : '图片、视频或音频' }}</small></span><span v-if="!firstFrame && !lastFrame" class="asset-count">{{ references.length + referenceVideos.length + referenceAudios.length }}</span><input v-if="!firstFrame && !lastFrame" type="file" accept="image/*,video/*,audio/*" multiple @change="pickMixedMedia"></label>
            <div v-if="references.length" class="reference-grid">
              <article v-for="(item, index) in references" :key="item.id" class="reference-item" draggable="true" @dragstart="draggedIndex = index" @dragover.prevent @drop="moveReference(draggedIndex, index)"><img :src="item.preview" :alt="`参考图片 ${index + 1}`"><span>{{ index + 1 }}</span><button type="button" aria-label="移除图片" @click="removeReference(index)"><XMarkIcon /></button></article>
            </div>
            <div v-if="referenceVideos.length || referenceAudios.length" class="media-list"><div v-for="(url, index) in referenceVideos" :key="`video-${url}`" class="media-chip"><VideoCameraIcon /><span>视频 {{ index + 1 }}</span><button type="button" aria-label="移除参考视频" @click="removeMedia('video', index)"><XMarkIcon /></button></div><div v-for="(url, index) in referenceAudios" :key="`audio-${url}`" class="media-chip"><MusicalNoteIcon /><span>音频 {{ index + 1 }}</span><button type="button" aria-label="移除参考音频" @click="removeMedia('audio', index)"><XMarkIcon /></button></div></div>
          </section>

          <section class="config-section prompt-section"><div class="section-title"><div><strong>提示词</strong></div><button v-if="form.prompt" type="button" @click="form.prompt = ''">清空</button></div><div class="prompt-editor"><div ref="promptHighlight" class="prompt-highlight" aria-hidden="true"><template v-for="(segment, index) in promptSegments" :key="index"><mark v-if="segment.mention">{{ segment.text }}</mark><span v-else>{{ segment.text }}</span></template></div><textarea ref="promptInput" v-model="form.prompt" rows="7" placeholder="描述主体、动作和镜头，输入 @ 可引用素材" @input="syncPromptMention" @click="syncPromptMention" @select="syncPromptMention" @scroll="syncPromptHighlight" @keyup="handlePromptKeyup" @keydown="handlePromptKeydown"></textarea><Teleport to="body"><div v-if="showPromptMenu && activeMention" class="mention-popover" :style="mentionMenuStyle"><div class="mention-list"><small>参考素材</small><button v-for="(item, index) in mentionItems" :key="item.key" type="button" :class="{ active: index === activeMentionIndex }" @mouseenter="activeMentionIndex = index" @mousedown.prevent="insertMention(item)"><img v-if="item.type === 'image'" :src="item.preview" :alt="item.label"><video v-else-if="item.type === 'video'" :src="item.preview" muted preload="metadata"></video><span v-else class="mention-audio"><MusicalNoteIcon /></span><span class="mention-label">{{ item.label }}</span></button></div><div class="mention-preview"><img v-if="activeMention.type === 'image'" :src="activeMention.preview" :alt="activeMention.label"><video v-else-if="activeMention.type === 'video'" :src="activeMention.preview" muted autoplay loop playsinline></video><div v-else class="mention-preview-audio"><MusicalNoteIcon /></div><footer><strong>{{ activeMention.label }}</strong><span>{{ mentionTypeLabel(activeMention.type) }}</span></footer></div></div></Teleport></div><span class="word-count">{{ form.prompt.length }} 字</span></section>

          <section class="config-section params-section">
            <div class="section-title"><div><strong>生成参数</strong></div></div>
            <div class="field"><label>画面比例</label><div class="ratio-options"><button v-for="item in videoAspectRatioOptions" :key="item.value" type="button" :class="{ active: form.aspectRatio === item.value }" :title="item.label" @click="form.aspectRatio = item.value"><span>{{ item.value }}</span></button></div></div>
            <div class="field-row"><div class="field"><label>清晰度</label><div class="segmented"><button v-for="item in availableResolutions" :key="item" type="button" :class="{ active: form.resolution === item }" @click="form.resolution = item">{{ item.toUpperCase() }}</button></div></div><div class="field"><label>时长 <small>{{ form.duration }} 秒（4–30）</small></label><div class="duration-input"><input v-model.number="form.duration" type="range" :min="durationRange.min" :max="durationRange.max" step="1"><input v-model.number="form.duration" type="number" :min="durationRange.min" :max="durationRange.max"></div></div></div>
            <label class="audio-toggle"><span><strong>生成同步音频</strong></span><input v-model="form.generateAudio" type="checkbox"><i></i></label>
          </section>
        </div>
        <div class="submit-bar"><p>{{ form.prompt.trim() ? `Seedance 2.5 · ${form.duration} 秒 · ${form.resolution.toUpperCase()}` : '请输入提示词开始生成' }}</p><button type="button" :disabled="!canSubmit" @click="submit"><SparklesIcon />{{ loading ? '生成中' : '开始生成' }}</button></div>
      </aside>

      <section class="task-area">
        <header class="task-heading"><div><h2>最近任务</h2><p>生成中的任务与结果会展示在这里</p></div></header>
        <article v-if="taskId || loading || error || videoUrl" class="task-card">
          <div class="task-card-head"><div><strong>{{ form.prompt.trim() || '视频生成任务' }}</strong><span>Seedance 2.5 · {{ form.duration }} 秒 · {{ form.resolution.toUpperCase() }} · {{ form.aspectRatio }}</span></div><div><span :class="['status-chip', statusTone]">{{ statusLabel }}</span><code v-if="taskId">{{ taskId }}</code></div></div>
          <div class="task-preview" :style="stageStyle">
            <video v-if="videoUrl" :src="resolveImageUrl(videoUrl)" controls playsinline></video>
            <div v-else-if="loading" class="task-state"><span class="state-icon"><VideoCameraIcon /></span><strong>{{ statusLabel }}</strong><div class="progress-track"><i :style="{ width: `${progress}%` }"></i></div><small>{{ progress }}%</small></div>
            <div v-else-if="error" class="task-state error"><ExclamationTriangleIcon /><strong>生成未完成</strong><p>{{ error }}</p></div>
            <div v-else class="task-state"><span class="state-icon"><PlayIcon /></span><strong>等待任务结果</strong></div>
          </div>
          <div class="task-card-foot"><span>{{ firstFrame || lastFrame ? '首尾帧' : `${references.length} 张参考图` }} · {{ referenceVideos.length }} 个视频 · {{ referenceAudios.length }} 个音频</span><span>{{ form.generateAudio ? '同步音频开启' : '静音输出' }}</span></div>
        </article>
        <div v-else class="task-empty"><span><VideoCameraIcon /></span><strong>暂无任务</strong><p>在左侧配置提示词与参数后开始生成，结果会在这里以任务卡片形式展示。</p></div>
      </section>
    </main>
  </MainLayout>
</template>

<script setup>
import { computed, onBeforeUnmount, onMounted, reactive, ref, watch } from 'vue'
import { ExclamationTriangleIcon, MusicalNoteIcon, PhotoIcon, SparklesIcon, VideoCameraIcon, XMarkIcon } from '@heroicons/vue/24/outline'
import { PlayIcon } from '@heroicons/vue/24/solid'
import MainLayout from '@/components/layout/MainLayout.vue'
import request, { resolveImageUrl } from '@/utils/request'
import { extractVideoResultUrl, isVideoTaskCompleteStatus, isVideoTaskFailedStatus, videoAspectRatioOptions, videoDurationRangeForModel, videoResolutionsForModel } from '@/utils/videoGeneration'

const form = reactive({ prompt: '', model: 'seedance-2-5', resolution: '720p', aspectRatio: '16:9', duration: 5, generateAudio: true })
const references = ref([]); const referenceVideos = ref([]); const referenceAudios = ref([]); const firstFrame = ref(''); const lastFrame = ref(''); const draggedIndex = ref(-1); const isDraggingFiles = ref(false); const frameDrag = ref(''); const promptInput = ref(null); const promptHighlight = ref(null); const showPromptMenu = ref(false); const mentionStart = ref(-1); const mentionQuery = ref(''); const activeMentionIndex = ref(0); const mentionMenuStyle = ref({}); const loading = ref(false); const progress = ref(0); const taskId = ref(''); const videoUrl = ref(''); const status = ref(''); const error = ref('')
const draftKey = 'video-generate-draft-v1'
try { const saved = JSON.parse(localStorage.getItem(draftKey) || '{}'); Object.assign(form, saved.form || {}); if (form.model !== 'seedance-2-5') form.model = 'seedance-2-5'; references.value = Array.isArray(saved.references) ? saved.references : []; referenceVideos.value = Array.isArray(saved.referenceVideos) ? saved.referenceVideos : []; referenceAudios.value = Array.isArray(saved.referenceAudios) ? saved.referenceAudios : []; firstFrame.value = saved.firstFrame || ''; lastFrame.value = saved.lastFrame || ''; taskId.value = saved.taskId || ''; videoUrl.value = saved.videoUrl || ''; status.value = saved.status || '' } catch { localStorage.removeItem(draftKey) }
const availableResolutions = computed(() => videoResolutionsForModel(form.model)); const durationRange = computed(() => videoDurationRangeForModel(form.model)); const canSubmit = computed(() => !!form.prompt.trim() && !loading.value); const stageStyle = computed(() => ({ '--stage-ratio': form.aspectRatio.replace(':', ' / ') })); const statusTone = computed(() => isVideoTaskFailedStatus(status.value) ? 'failed' : (isVideoTaskCompleteStatus(status.value) ? 'done' : 'running')); const statusLabel = computed(() => ({ QUEUED: '任务排队中', RUNNING: '正在生成视频', SUCCEEDED: '生成完成', FAILED: '生成失败', EXPIRED: '任务已超时' }[status.value] || (loading.value ? '正在创建任务' : '等待生成')))
const mentionItems = computed(() => [
  ...(firstFrame.value ? [{ key: 'first-frame', label: '首帧', type: 'image', preview: resolveImageUrl(firstFrame.value) }] : []),
  ...(lastFrame.value ? [{ key: 'last-frame', label: '尾帧', type: 'image', preview: resolveImageUrl(lastFrame.value) }] : []),
  ...references.value.map((item, index) => ({ key: `image-${index}`, label: `参考图${index + 1}`, type: 'image', preview: item.preview })),
  ...referenceVideos.value.map((url, index) => ({ key: `video-${index}`, label: `参考视频${index + 1}`, type: 'video', preview: resolveImageUrl(url) })),
  ...referenceAudios.value.map((url, index) => ({ key: `audio-${index}`, label: `参考音频${index + 1}`, type: 'audio', preview: resolveImageUrl(url) })),
].filter(item => item.label.includes(mentionQuery.value)))
const activeMention = computed(() => mentionItems.value[activeMentionIndex.value] || null)
const promptSegments = computed(() => { const pattern = /@(首帧|尾帧|参考图\d+|参考视频\d+|参考音频\d+)/g; const segments = []; let cursor = 0; for (const match of form.prompt.matchAll(pattern)) { if (match.index > cursor) segments.push({ text: form.prompt.slice(cursor, match.index), mention: false }); segments.push({ text: match[0], mention: true }); cursor = match.index + match[0].length } if (cursor < form.prompt.length) segments.push({ text: form.prompt.slice(cursor), mention: false }); return segments })
watch(availableResolutions, options => { if (!options.includes(form.resolution)) form.resolution = options[options.length - 1] })
watch(durationRange, range => { form.duration = Math.min(range.max, Math.max(range.min, Number(form.duration) || 5)) }, { immediate: true })
async function uploadReferenceFile(file) { const body = new FormData(); body.append('file', file); body.append('mime_type', file.type); const res = await request.post('/upload/image', body); return res.data?.url || '' }
async function addReferenceFiles(files) { error.value = ''; for (const file of Array.from(files).filter(item => item.type.startsWith('image/')).slice(0, 9 - references.value.length)) { try { const url = await uploadReferenceFile(file); if (url) references.value.push({ id: `${Date.now()}-${Math.random()}`, preview: resolveImageUrl(url), data: url }) } catch (err) { error.value = err?.response?.data?.error || err?.message || '上传参考图片失败' } } }
function clearReferenceMedia() { references.value = []; referenceVideos.value = []; referenceAudios.value = [] }
async function setFrame(which, file) { if (!file?.type.startsWith('image/')) return; const url = await uploadReferenceFile(file); clearReferenceMedia(); if (which === 'first') firstFrame.value = url; else lastFrame.value = url }
async function pickFrame(which, event) { await setFrame(which, event.target.files?.[0]); event.target.value = '' }
async function dropFrame(which, event) { frameDrag.value = ''; await setFrame(which, event.dataTransfer?.files?.[0]) }
async function addMediaFiles(kind, files) { error.value = ''; const target = kind === 'video' ? referenceVideos : referenceAudios; for (const file of Array.from(files).slice(0, 3 - target.value.length)) { if (file.type.startsWith(`${kind}/`)) { try { const url = await uploadReferenceFile(file); if (url) target.value.push(url) } catch (err) { error.value = err?.response?.data?.error || err?.message || `上传参考${kind === 'video' ? '视频' : '音频'}失败` } } } }
async function addMixedMedia(files) { if (firstFrame.value || lastFrame.value) return; const list = Array.from(files); await addReferenceFiles(list); await addMediaFiles('video', list); await addMediaFiles('audio', list) }
async function pickMixedMedia(event) { await addMixedMedia(event.target.files || []); event.target.value = '' }
async function dropMixedMedia(event) { isDraggingFiles.value = false; await addMixedMedia(event.dataTransfer?.files || []) }
function removeMedia(kind, index) { const target = kind === 'video' ? referenceVideos : referenceAudios; target.value.splice(index, 1) }
function removeReference(index) { const [removed] = references.value.splice(index, 1); if (removed?.preview) URL.revokeObjectURL(removed.preview) }
function moveReference(from, to) { if (from < 0 || to < 0 || from >= references.value.length || to >= references.value.length || from === to) return; const [item] = references.value.splice(from, 1); references.value.splice(to, 0, item); draggedIndex.value = -1 }
function updateMentionMenuPosition() { if (!showPromptMenu.value || !promptInput.value) return; const rect = promptInput.value.getBoundingClientRect(); const width = Math.min(540, window.innerWidth - 24); const left = Math.max(12, Math.min(rect.left, window.innerWidth - width - 12)); const height = Math.min(300, window.innerHeight - 24); const top = rect.top >= height + 12 ? rect.top - height - 8 : Math.min(rect.bottom + 8, window.innerHeight - height - 12); mentionMenuStyle.value = { width: `${width}px`, height: `${height}px`, left: `${left}px`, top: `${Math.max(12, top)}px` } }
function closePromptMention() { showPromptMenu.value = false; mentionStart.value = -1; mentionQuery.value = '' }
function syncPromptHighlight() { if (!promptInput.value || !promptHighlight.value) return; promptHighlight.value.scrollTop = promptInput.value.scrollTop; promptHighlight.value.scrollLeft = promptInput.value.scrollLeft }
function syncPromptMention() { const input = promptInput.value; if (!input || document.activeElement !== input) { closePromptMention(); return } const cursor = input.selectionStart; if (cursor !== input.selectionEnd) { closePromptMention(); return } const match = input.value.slice(0, cursor).match(/@([^@\s]*)$/); if (!match) { closePromptMention(); return } const nextStart = cursor - match[0].length; const changedMention = !showPromptMenu.value || mentionStart.value !== nextStart; mentionStart.value = nextStart; mentionQuery.value = match[1] || ''; showPromptMenu.value = mentionItems.value.length > 0; if (changedMention) activeMentionIndex.value = 0; else activeMentionIndex.value = Math.min(activeMentionIndex.value, Math.max(0, mentionItems.value.length - 1)); requestAnimationFrame(updateMentionMenuPosition) }
function handlePromptKeydown(event) { if (!showPromptMenu.value || !mentionItems.value.length) return; if (event.key === 'ArrowDown') { event.preventDefault(); activeMentionIndex.value = (activeMentionIndex.value + 1) % mentionItems.value.length } else if (event.key === 'ArrowUp') { event.preventDefault(); activeMentionIndex.value = (activeMentionIndex.value - 1 + mentionItems.value.length) % mentionItems.value.length } else if (event.key === 'Enter') { event.preventDefault(); insertMention(activeMention.value) } else if (event.key === 'Escape') { event.preventDefault(); showPromptMenu.value = false } }
function handlePromptKeyup(event) { if (['ArrowUp', 'ArrowDown', 'Escape'].includes(event.key)) return; syncPromptMention() }
function mentionTypeLabel(type) { return type === 'video' ? 'video' : type === 'audio' ? 'audio' : 'image' }
function handleDocumentPointerDown(event) { if (!showPromptMenu.value) return; if (promptInput.value?.contains(event.target) || event.target.closest?.('.mention-popover')) return; closePromptMention() }
function insertMention(item) { const input = promptInput.value; const cursor = input?.selectionStart ?? form.prompt.length; const start = mentionStart.value >= 0 ? mentionStart.value : cursor; form.prompt = `${form.prompt.slice(0, start)}@${item.label} ${form.prompt.slice(cursor)}`; showPromptMenu.value = false; mentionQuery.value = ''; requestAnimationFrame(() => { const nextCursor = start + item.label.length + 2; input?.focus(); input?.setSelectionRange(nextCursor, nextCursor) }) }
async function submit() { if (!canSubmit.value) return; loading.value = true; progress.value = 6; error.value = ''; videoUrl.value = ''; taskId.value = ''; status.value = ''; const timer = window.setInterval(() => { progress.value = Math.min(92, progress.value + 3) }, 1400); try { const res = await request.post('/video/generate', { prompt: form.prompt.trim(), model: form.model, resolution: form.resolution, aspect_ratio: form.aspectRatio, duration: form.duration, generate_audio: form.generateAudio, image: firstFrame.value, image_end: lastFrame.value, reference_images: references.value.map(item => item.data), reference_videos: referenceVideos.value, reference_audios: referenceAudios.value }); taskId.value = res.data?.task_id || ''; status.value = String(res.data?.status || 'QUEUED').toUpperCase(); videoUrl.value = extractVideoResultUrl(res.data || {}); if (!videoUrl.value && taskId.value) await pollTask(); if (!videoUrl.value) throw new Error('任务完成但未返回视频地址') } catch (err) { error.value = err?.response?.data?.error || err?.message || '视频生成失败'; if (!status.value) status.value = 'FAILED' } finally { window.clearInterval(timer); loading.value = false; progress.value = videoUrl.value ? 100 : 0 } }
async function pollTask() { for (let attempt = 0; attempt < 300; attempt += 1) { await new Promise(resolve => window.setTimeout(resolve, 3000)); const res = await request.get(`/video/tasks/${encodeURIComponent(form.model)}/${encodeURIComponent(taskId.value)}`); status.value = String(res.data?.status || '').toUpperCase(); videoUrl.value = extractVideoResultUrl(res.data || {}); if (isVideoTaskCompleteStatus(status.value) || videoUrl.value) return; if (isVideoTaskFailedStatus(status.value)) throw new Error(res.data?.error?.message || '视频任务失败') } status.value = 'EXPIRED'; throw new Error('视频生成超时，请稍后查看历史记录') }
watch(() => ({ form: { ...form }, references: references.value, referenceVideos: referenceVideos.value, referenceAudios: referenceAudios.value, firstFrame: firstFrame.value, lastFrame: lastFrame.value, taskId: taskId.value, videoUrl: videoUrl.value, status: status.value }), value => localStorage.setItem(draftKey, JSON.stringify(value)), { deep: true })
onMounted(async () => { if (!taskId.value || videoUrl.value || isVideoTaskCompleteStatus(status.value) || isVideoTaskFailedStatus(status.value)) return; loading.value = true; progress.value = 8; try { await pollTask() } catch (err) { error.value = err?.response?.data?.error || err?.message || '恢复视频任务失败' } finally { loading.value = false; progress.value = videoUrl.value ? 100 : 0 } })
onMounted(() => { window.addEventListener('resize', updateMentionMenuPosition); window.addEventListener('scroll', updateMentionMenuPosition, true); document.addEventListener('pointerdown', handleDocumentPointerDown) })
onBeforeUnmount(() => { window.removeEventListener('resize', updateMentionMenuPosition); window.removeEventListener('scroll', updateMentionMenuPosition, true); document.removeEventListener('pointerdown', handleDocumentPointerDown) })
</script>

<style scoped>
